**Title:** Refactor authentication module to use JWT

**Description:** This PR replaces the legacy session-based authentication with a JWT implementation. The changes include updating the login controller, adding a token generation service, and modifying middleware to verify tokens.

**Code Changes:**
```diff
- // legacy login
- const session = require('express-session');
- app.use(session({ secret: 'oldSecret', resave: false, saveUninitialized: true }));
+ // JWT login
+ const jwt = require('jsonwebtoken');
+ const tokenService = require('./services/tokenService');
@@
- res.redirect('/dashboard');
+ const token = tokenService.createToken(user.id);
+ res.json({ token });
@@
- function ensureAuthenticated(req, res, next) {
-   if (req.session.user) return next();
-   res.redirect('/login');
- }
+ function ensureAuthenticated(req, res, next) {
+   const authHeader = req.headers.authorization;
+   if (!authHeader) return res.status(401).send('Unauthorized');
+   const token = authHeader.split(' ')[1];
+   try {
+     req.user = jwt.verify(token, process.env.JWT_SECRET);
+     next();
+   } catch (err) {
+     res.status(401).send('Invalid token');
+   }
+ }
```

