# data_processor.py

"""
Bug Report ID: 3421
Title: process_data_v2 raises IndexError on empty input list
Description: When calling process_data_v2([]), the function attempts to access the first element of the list without checking if the list is non‑empty, leading to an IndexError. This is a regression introduced in the latest feature branch.

Feature Request: Add optional caching to data processing functions to improve repeated calls performance.
"""

import time
from functools import lru_cache

def process_data_v1(data):
    """Process a list of numbers by computing the cumulative sum.
    This is the original implementation.
    """
    result = []
    total = 0
    for num in data:
        total += num
        result.append(total)
    return result

def process_data_v2(data):
    """Process a list of numbers using a while‑loop and indexing.
    New implementation introduced for better readability.
    """
    result = []
    i = 0
    while i < len(data):
        if i == 0:
            result.append(data[i])
        else:
            result.append(result[i-1] + data[i])
        i += 1
    return result

@lru_cache(maxsize=128)
def cached_process_data_v1(data_tuple):
    """Cached wrapper for process_data_v1. Accepts a tuple to be hashable.
    """
    return process_data_v1(list(data_tuple))

def benchmark(fn, data, runs=1000):
    start = time.perf_counter()
    for _ in range(runs):
        fn(data)
    end = time.perf_counter()
    return (end - start) / runs

